<?php require 'includes/bootstrap.php';$error='';if ($_SERVER['REQUEST_METHOD']==='POST') {check_csrf();$email=strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');$q=db()->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();if($u && password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];redirect('dashboard.php');}else $error='البريد الإلكتروني أو كلمة المرور غير صحيحة.';}header_html('تسجيل الدخول'); ?>
<section class="wrapper auth-area"><div class="auth-card"><span class="eyebrow">أهلًا بعودتك</span><h1>تسجيل الدخول</h1><?php if($error):?><div class="alert error" role="alert"><?=e($error)?></div><?php endif;?><form method="post" data-validate><?=csrf_input()?><label>البريد الإلكتروني<input type="email" name="email" required autocomplete="email"></label><label>كلمة المرور<input type="password" name="password" required autocomplete="current-password"></label><button class="button primary full">الدخول ↗</button></form><p>ليس لديك حساب؟ <a href="register.php">أنشئ حسابًا</a></p></div></section><?php footer_html(); ?>
